mapper.select:
SELECT sta.id, sta.activity_name AS activityName, sta.plan_id AS tourPlanId, stp.plan_name AS planName, sta.apply_start_date AS applyStartDate, sta.apply_end_date AS applyEndDate, sta.activity_start_date AS activityStartDate, sta.activity_end_date AS activityEndDate, sta.price, sta.recruit_num AS recruitNum, sta.registered_num AS registeredNum, sta.status, sta.remark, sta.create_time AS createTime, sta.update_time AS updateTime, COALESCE(( SELECT COUNT(*) FROM user_collect uc WHERE uc.target_type = 'study_activity' AND uc.target_id = CAST(sta.id AS CHAR) ), 0) AS collectNumber, CASE WHEN #{userId} IS NOT NULL AND EXISTS ( SELECT 1 FROM user_collect uc2 WHERE uc2.user_id = #{userId} AND uc2.target_type = 'study_activity' AND uc2.target_id = CAST(sta.id AS CHAR) ) THEN 1 ELSE 0 END AS isCollect FROM study_tour_activity sta LEFT JOIN study_tour_plan stp ON sta.plan_id = stp.id
INNER JOIN study_tour_base stb ON stp.base_id = stb.id
AND stb.user_id = #{merchantUserId}
AND sta.activity_name LIKE CONCAT('%', #{activityName}, '%')
AND sta.plan_id = #{tourPlanId}
AND sta.status = #{status}
AND sta.status != 5
ORDER BY sta.create_time DESC
